package net.minecraft.world.entity.vehicle;public class AbstractMinecart{public static class Vec3{public final double x,y,z;public Vec3(double x,double y,double z){this.x=x;this.y=y;this.z=z;}}public record Box(double w,double d){public double getXsize(){return w;}public double getZsize(){return d;}}public double x,y,z;public Vec3 motion;public Box box=new Box(0.98f,0.98f);public Vec3 getDeltaMovement(){return motion;}public double getX(){return x;}public double getY(){return y;}public double getZ(){return z;}public Box getBoundingBox(){return box;}}